# Label, heading, and description. Article membership is generated from each
# branch's own catalog pools rather than copied from another locale.
THEME_COPY = {
    "en": {
        "starter": ("Start here", "A strong first tour of the Foundation", "Accessible reports that show several ways an SCP article can work."),
        "community": ("Community picks", "Chosen and discussed by readers", "Highly rated and curated work that has stayed in community conversation."),
        "horror": ("Horror", "Slow dread and sharp scares", "Clinical unease, found footage, hostile places, and ideas that follow you."),
        "short": ("Short reads", "Compact articles with a clean turn", "Good choices when you want a complete read in a few minutes."),
        "emotional": ("Emotional", "Stories that leave an afterimage", "Family, loss, companionship, and difficult forms of hope."),
        "mind": ("Mind & information", "Memory is part of the document", "Antimemetics, cognition, information hazards, and formal play."),
        "scifi": ("Science fiction", "Big ideas across time and space", "Cosmic scale, alternate worlds, technology, and speculative systems."),
        "tales": ("Tales", "Beyond the containment report", "Narrative work that follows people, institutions, and consequences."),
        "world": ("Canons & GoIs", "Follow a setting further", "Connected writing and other organizations' views of the Foundation universe."),
        "underread": ("Underread", "Excellent work outside the usual classics", "Lower-profile pieces selected from deeper in the current catalog."),
    },
}


def _translated_themes(locale, values):
    """Attach localized tuples without repeating dictionary boilerplate."""
    THEME_COPY[locale] = dict(zip(
        ["starter", "local", "local_more", "horror", "short", "long", "emotional", "mind", "scifi", "tales", "world", "underread", "funny", "history", "folklore", "interactive", "campus", "recent"],
        values,
    ))


